172	            _sessionExpiryNotifier.notifyExpired();
173	          }
174	          return failure;
175	        }
176	      } catch (_) {
177	        // Falls through to the generic mapping below — same "never throw"
178	        // rationale every other decode step in this file already follows.
179	      }
180	    }
181	    return _mapDioException(e);
