233	  /// than letting a `FormatException` escape this mapping step unmapped
234	  /// (RNF09).
235	  bool _isAnonKeyOnlyCall(DioException e) {
236	    String function;
237	    try {
238	      function = HeaderInterceptor.functionNameOf(e.requestOptions.path);
239	    } catch (_) {
240	      function = '';
241	    }
242	    return HeaderInterceptor.anonKeyOnlyFunctions.contains(function);
243	  }
244	}
