101	          return;
102	        }
103	        messagesResult.match(
104	          (failure) => emit(ChatBootstrapError(failure)),
105	          (messages) => emit(
106	            ChatReady(
107	              sessionId: session.id,
108	              messages: messages.map(_fromDomain).toList(),
109	            ),
110	          ),
111	        );
112	      },
113	    );
114	  }
115	
116	  ChatUiMessage _fromDomain(ChatMessage message) => ChatUiMessage(
117	    id: message.id,
118	    role: message.role,
119	    content: message.content,
120	    status: message.status,
121	  );
122	
123	  /// Boundaries: optimistic user bubble, then subscribes to
124	  /// `ChatRepository.sendMessage`'s own stream, appending tokens as they
125	  /// arrive and finalizing/failing the AI bubble on `done`/any `Left` —
126	  /// the bubble's own [ChatUiMessage.content] is never cleared on failure
127	  /// (I/O matrix), only its [ChatUiMessage.status] changes.
128	  ///
129	  /// A no-op while [state] isn't [ChatReady] (bootstrap still in flight
