173	    final completer = Completer<void>();
174	    _sendCompleter = completer;
175	    _sendSubscription = _repository
176	        .sendMessage(current.sessionId, trimmed)
177	        .listen(
178	          (event) {
179	            event.match(
180	              (failure) => _markFailed(aiMessage.id),
181	              (streamEvent) => _applyStreamEvent(aiMessage.id, streamEvent),
182	            );
183	          },
184	          onError: (Object _, StackTrace _) {
185	            // RNF09: no exception escapes the cubit — a stream-level
186	            // error (shouldn't happen, `ChatRemoteDataSource.sendMessage`
187	            // never lets one through unmapped) still only fails the
188	            // bubble, never crashes.
189	            _markFailed(aiMessage.id);
