206	  }
207	
208	  /// Clears both the internal re-entrancy guard and the UI-facing
209	  /// [ChatReady.isSending] signal once a send's stream has ended (`done`,
210	  /// an in-band error, or a stream-level error) — the single place both
211	  /// flip back together.
212	  void _finishSending() {
213	    _isSending = false;
214	    if (isClosed) {
215	      return;
216	    }
217	    final current = state;
218	    if (current is ChatReady) {
219	      emit(current.copyWith(isSending: false));
220	    }
221	  }
222	
223	  void _applyStreamEvent(String aiMessageId, ChatStreamEvent event) {
224	    if (isClosed) {
225	      return;
226	    }
227	    final current = state;
228	    if (current is! ChatReady) {
229	      return;
230	    }
231	    switch (event) {
232	      case ChatMessageCreatedEvent():
233	        // Design Notes: the persisted *user*-message id — no UI-facing
