238	        emit(
239	          current.copyWith(
240	            messages: [
241	              for (final message in current.messages)
242	                if (message.id == aiMessageId)
243	                  message.copyWith(content: message.content + delta)
244	                else
245	                  message,
246	            ],
247	          ),
248	        );
249	      case ChatDoneEvent():
250	        emit(
251	          current.copyWith(
252	            messages: [
253	              for (final message in current.messages)
254	                if (message.id == aiMessageId)
255	                  message.copyWith(status: ChatMessageStatus.complete)
256	                else
257	                  message,
258	            ],
259	          ),
260	        );
261	    }
262	  }
263	
264	  /// I/O matrix: "Mid-stream drop"/"In-band `error` event" — marks the one
265	  /// bubble `failed`, by id, leaving its already-streamed-in text exactly
266	  /// as-is (never cleared, Boundaries).
267	  void _markFailed(String aiMessageId) {
268	    if (isClosed) {
269	      return;
270	    }
271	    final current = state;
272	    if (current is! ChatReady) {
273	      return;
274	    }
275	    emit(
276	      current.copyWith(
277	        messages: [
278	          for (final message in current.messages)
279	            if (message.id == aiMessageId)
280	              message.copyWith(status: ChatMessageStatus.failed)
281	            else
282	              message,
283	        ],
284	      ),
285	    );
286	  }
