288	  String _nextLocalId() => 'local-${_localIdCounter++}';
289	
290	  @override
291	  Future<void> close() {
292	    _sendSubscription?.cancel();
293	    final completer = _sendCompleter;
294	    if (completer != null && !completer.isCompleted) {
295	      completer.complete();
296	    }
297	    _sendCompleter = null;
298	    return super.close();
299	  }
